<?php
namespace App\Http\Controllers; use App\Models\{ResourceUrl,Project}; use App\Services\AuditService; use Illuminate\Http\Request;
class ResourceUrlController extends Controller { private function data(Request $r){return $r->validate(['project_id'=>'nullable|exists:projects,id','label'=>'required|max:150','url'=>'required|max:2048','type'=>'required|max:80','notes'=>'nullable']);} public function index(){return view('urls.index',['items'=>ResourceUrl::with('project')->latest()->get()]);} public function create(){return view('urls.form',['item'=>new ResourceUrl,'projects'=>Project::orderBy('name')->get()]);} public function store(Request $r){$x=ResourceUrl::create($this->data($r));AuditService::log('RESOURCE_CREATED',$x->label,$x);return redirect()->route('urls.index')->with('ok','Recurso guardado.');} public function edit(ResourceUrl $url){return view('urls.form',['item'=>$url,'projects'=>Project::orderBy('name')->get()]);} public function update(Request $r,ResourceUrl $url){$url->update($this->data($r));AuditService::log('RESOURCE_UPDATED',$url->label,$url);return redirect()->route('urls.index')->with('ok','Recurso actualizado.');} public function destroy(ResourceUrl $url){$label=$url->label;$url->delete();AuditService::log('RESOURCE_DELETED',$label);return redirect()->route('urls.index')->with('ok','Recurso eliminado.');}}
